//! Golden-corpus test for the `difflib.SequenceMatcher` port.
//!
//! `testdata/difflib_ratios.jsonl` was generated by *running* CPython's `difflib` — not
//! hand-written — over a few thousand varied inputs: unicode, empty strings, identical
//! strings, mutation ladders, random alphabet soup, HTML blobs, tag sequences, and several
//! hundred cases with `len(b) >= 200` so the autojunk heuristic is exercised on both sides
//! of its threshold. The corpus header records the exact CPython version used.
//!
//! The generator is vendored at `testdata/gen_difflib_corpus.py` and is seeded, so the
//! corpus can be regenerated or extended reproducibly:
//! `python3 testdata/gen_difflib_corpus.py testdata/difflib_ratios.jsonl`.
//!
//! Every record stores the IEEE-754 bit pattern of the Python result, and this test
//! asserts **bit equality** — not approximate equality. A single ULP of drift changes
//! relocation outcomes at the `40 %` threshold, so anything looser would not be a gate.
//!
//! Four record kinds are covered:
//!
//! | kind | Python expression |
//! |---|---|
//! | `str` | `SequenceMatcher(None, a, b).ratio()` over two strings |
//! | `seq` | `SequenceMatcher(None, a, b).ratio()` over two tuples of strings |
//! | `dict_diff` | `Selector.__calculate_dict_diff(d1, d2)` |
//! | `score` | `Selector.__calculate_similarity_score(original, candidate)` |
//!
//! The corpus is JSON Lines. Integration tests only see the crate's public API and its
//! dev-dependencies, and `browser-core` declares none, so this file carries a small
//! self-contained JSON reader rather than pulling in `serde_json`.

use std::fmt::Write as _;
use std::path::PathBuf;

use browser_core::fingerprint::{dict_diff, similarity_score, AttributeDict, ElementFingerprint};
use browser_core::similarity::{ratio_seq, ratio_str};

// ---------------------------------------------------------------- minimal JSON reader

/// A parsed JSON value. Numbers keep their source text so that 64-bit integers survive
/// (an `f64` cannot hold `4607182418800017408` exactly).
#[derive(Debug, Clone, PartialEq)]
enum Json {
    Null,
    Bool(bool),
    Num(String),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

impl Json {
    fn as_str(&self) -> &str {
        match self {
            Json::Str(s) => s,
            other => panic!("expected a JSON string, got {other:?}"),
        }
    }

    fn as_array(&self) -> &[Json] {
        match self {
            Json::Arr(items) => items,
            other => panic!("expected a JSON array, got {other:?}"),
        }
    }

    fn as_u64(&self) -> u64 {
        match self {
            Json::Num(text) => text
                .parse::<u64>()
                .unwrap_or_else(|e| panic!("bad u64 {text:?}: {e}")),
            other => panic!("expected a JSON number, got {other:?}"),
        }
    }

    /// Looks up a key in an object, returning `None` when the key is absent.
    fn get(&self, key: &str) -> Option<&Json> {
        match self {
            Json::Obj(pairs) => pairs.iter().find(|(k, _)| k == key).map(|(_, v)| v),
            other => panic!("expected a JSON object, got {other:?}"),
        }
    }

    /// Looks up a required key.
    fn field(&self, key: &str) -> &Json {
        self.get(key)
            .unwrap_or_else(|| panic!("missing required key {key:?} in {self:?}"))
    }

    /// `Some(text)` for a string, `None` for `null` or an absent key.
    fn opt_string(value: Option<&Json>) -> Option<String> {
        match value {
            None | Some(Json::Null) => None,
            Some(Json::Str(s)) => Some(s.clone()),
            Some(other) => panic!("expected a string or null, got {other:?}"),
        }
    }

    fn string_vec(&self) -> Vec<String> {
        self.as_array()
            .iter()
            .map(|v| v.as_str().to_owned())
            .collect()
    }

    /// A JSON object read as an ordered attribute map.
    fn attr_map(&self) -> AttributeDict {
        match self {
            Json::Obj(pairs) => pairs
                .iter()
                .map(|(k, v)| (k.clone(), v.as_str().to_owned()))
                .collect::<AttributeDict>(),
            other => panic!("expected a JSON object, got {other:?}"),
        }
    }
}

struct Parser<'a> {
    src: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(src: &'a str) -> Self {
        Self {
            src: src.as_bytes(),
            pos: 0,
        }
    }

    fn peek(&self) -> Option<u8> {
        self.src.get(self.pos).copied()
    }

    fn bump(&mut self) -> u8 {
        let byte = self.src[self.pos];
        self.pos += 1;
        byte
    }

    fn skip_ws(&mut self) {
        while matches!(self.peek(), Some(b' ' | b'\t' | b'\n' | b'\r')) {
            self.pos += 1;
        }
    }

    fn expect(&mut self, byte: u8) {
        self.skip_ws();
        assert_eq!(
            self.peek(),
            Some(byte),
            "expected {:?} at byte {}",
            byte as char,
            self.pos
        );
        self.pos += 1;
    }

    fn literal(&mut self, word: &str) {
        assert!(
            self.src[self.pos..].starts_with(word.as_bytes()),
            "expected literal {word:?} at byte {}",
            self.pos
        );
        self.pos += word.len();
    }

    fn parse(&mut self) -> Json {
        self.skip_ws();
        match self.peek().expect("unexpected end of JSON input") {
            b'{' => self.parse_object(),
            b'[' => self.parse_array(),
            b'"' => Json::Str(self.parse_string()),
            b't' => {
                self.literal("true");
                Json::Bool(true)
            }
            b'f' => {
                self.literal("false");
                Json::Bool(false)
            }
            b'n' => {
                self.literal("null");
                Json::Null
            }
            _ => self.parse_number(),
        }
    }

    fn parse_object(&mut self) -> Json {
        self.expect(b'{');
        let mut pairs = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b'}') {
            self.pos += 1;
            return Json::Obj(pairs);
        }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.expect(b':');
            let value = self.parse();
            pairs.push((key, value));
            self.skip_ws();
            match self.peek() {
                Some(b',') => self.pos += 1,
                Some(b'}') => {
                    self.pos += 1;
                    break;
                }
                other => panic!("expected ',' or '}}' at byte {}, got {other:?}", self.pos),
            }
        }
        Json::Obj(pairs)
    }

    fn parse_array(&mut self) -> Json {
        self.expect(b'[');
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b']') {
            self.pos += 1;
            return Json::Arr(items);
        }
        loop {
            items.push(self.parse());
            self.skip_ws();
            match self.peek() {
                Some(b',') => self.pos += 1,
                Some(b']') => {
                    self.pos += 1;
                    break;
                }
                other => panic!("expected ',' or ']' at byte {}, got {other:?}", self.pos),
            }
        }
        Json::Arr(items)
    }

    fn parse_number(&mut self) -> Json {
        let start = self.pos;
        while matches!(
            self.peek(),
            Some(b'-' | b'+' | b'.' | b'e' | b'E' | b'0'..=b'9')
        ) {
            self.pos += 1;
        }
        let text = std::str::from_utf8(&self.src[start..self.pos]).expect("number is ASCII");
        assert!(!text.is_empty(), "empty number at byte {start}");
        Json::Num(text.to_owned())
    }

    /// Reads a JSON string, decoding every escape form including surrogate pairs. The
    /// corpus is written with `ensure_ascii=False`, so most characters arrive as raw
    /// UTF-8 and are copied through untouched.
    fn parse_string(&mut self) -> String {
        self.expect(b'"');
        let mut out = String::new();
        loop {
            let byte = self.bump();
            match byte {
                b'"' => break,
                b'\\' => {
                    let esc = self.bump();
                    match esc {
                        b'"' => out.push('"'),
                        b'\\' => out.push('\\'),
                        b'/' => out.push('/'),
                        b'b' => out.push('\u{0008}'),
                        b'f' => out.push('\u{000c}'),
                        b'n' => out.push('\n'),
                        b'r' => out.push('\r'),
                        b't' => out.push('\t'),
                        b'u' => out.push(self.parse_unicode_escape()),
                        other => panic!("unknown escape \\{}", other as char),
                    }
                }
                _ => {
                    // Copy the whole UTF-8 sequence this byte starts.
                    let start = self.pos - 1;
                    let width = utf8_width(byte);
                    self.pos = start + width;
                    let text = std::str::from_utf8(&self.src[start..self.pos])
                        .expect("corpus is valid UTF-8");
                    out.push_str(text);
                }
            }
        }
        out
    }

    fn parse_hex4(&mut self) -> u16 {
        let mut value: u16 = 0;
        for _ in 0..4 {
            let digit = char::from(self.bump())
                .to_digit(16)
                .expect("four hex digits after \\u");
            value = value * 16 + u16::try_from(digit).expect("hex digit fits in u16");
        }
        value
    }

    fn parse_unicode_escape(&mut self) -> char {
        let first = self.parse_hex4();
        if (0xD800..=0xDBFF).contains(&first) {
            assert_eq!(self.bump(), b'\\', "lone high surrogate");
            assert_eq!(self.bump(), b'u', "lone high surrogate");
            let second = self.parse_hex4();
            assert!(
                (0xDC00..=0xDFFF).contains(&second),
                "high surrogate not followed by a low surrogate"
            );
            let code =
                0x1_0000 + ((u32::from(first) - 0xD800) << 10) + (u32::from(second) - 0xDC00);
            return char::from_u32(code).expect("valid surrogate pair");
        }
        char::from_u32(u32::from(first)).expect("valid BMP escape")
    }
}

fn utf8_width(first_byte: u8) -> usize {
    match first_byte {
        0x00..=0x7F => 1,
        0xC0..=0xDF => 2,
        0xE0..=0xEF => 3,
        _ => 4,
    }
}

// ------------------------------------------------------------------------- the corpus

fn corpus_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../testdata/difflib_ratios.jsonl")
}

fn load_corpus() -> Vec<Json> {
    let path = corpus_path();
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
    text.lines()
        .filter(|line| !line.trim().is_empty() && !line.starts_with('#'))
        .map(|line| {
            let mut parser = Parser::new(line);
            let value = parser.parse();
            parser.skip_ws();
            assert_eq!(parser.pos, line.len(), "trailing junk in record: {line}");
            value
        })
        .collect()
}

fn fingerprint_from(value: &Json) -> ElementFingerprint {
    ElementFingerprint {
        tag: value.field("tag").as_str().to_owned(),
        attributes: value.field("attributes").attr_map(),
        text: Json::opt_string(value.get("text")),
        path: value.field("path").string_vec(),
        parent_name: Json::opt_string(value.get("parent_name")),
        parent_attribs: value.get("parent_attribs").map(Json::attr_map),
        parent_text: Json::opt_string(value.get("parent_text")),
        siblings: value.get("siblings").map(Json::string_vec),
        children: value.get("children").map(Json::string_vec),
    }
}

fn pairs_to_map(value: &Json) -> AttributeDict {
    value
        .as_array()
        .iter()
        .map(|pair| {
            let kv = pair.as_array();
            assert_eq!(kv.len(), 2, "dict_diff entries are [key, value] pairs");
            (kv[0].as_str().to_owned(), kv[1].as_str().to_owned())
        })
        .collect::<AttributeDict>()
}

/// Truncates a long value for the failure message.
fn preview(value: &Json) -> String {
    let mut rendered = format!("{value:?}");
    if rendered.chars().count() > 160 {
        let head: String = rendered.chars().take(160).collect();
        rendered = head;
        let _ = write!(rendered, "… (truncated)");
    }
    rendered
}

#[test]
fn every_python_ratio_is_reproduced_bit_for_bit() {
    let records = load_corpus();
    assert!(
        records.len() >= 2000,
        "corpus looks truncated: {} records",
        records.len()
    );

    let mut counts = [0usize; 4];
    let mut autojunk_cases = 0usize;

    for record in &records {
        let kind = record.field("kind").as_str();
        let expected_bits = record.field("bits").as_u64();
        let a = record.field("a");
        let b = record.field("b");

        let actual = match kind {
            "str" => {
                counts[0] += 1;
                if b.as_str().chars().count() >= 200 {
                    autojunk_cases += 1;
                }
                ratio_str(a.as_str(), b.as_str())
            }
            "seq" => {
                counts[1] += 1;
                let av = a.string_vec();
                let bv = b.string_vec();
                if bv.len() >= 200 {
                    autojunk_cases += 1;
                }
                ratio_seq(&av, &bv)
            }
            "dict_diff" => {
                counts[2] += 1;
                dict_diff(&pairs_to_map(a), &pairs_to_map(b))
            }
            "score" => {
                counts[3] += 1;
                similarity_score(&fingerprint_from(a), &fingerprint_from(b))
            }
            other => panic!("unknown record kind {other:?}"),
        };

        assert_eq!(
            actual.to_bits(),
            expected_bits,
            "kind={kind}\n  a = {}\n  b = {}\n  python = {} (bits {expected_bits})\n  rust   = {} (bits {})",
            preview(a),
            preview(b),
            f64::from_bits(expected_bits),
            actual,
            actual.to_bits()
        );
    }

    // The corpus must actually cover the interesting shapes, otherwise a future
    // regeneration could silently weaken the gate.
    let [strs, seqs, dicts, scores] = counts;
    assert!(strs >= 1000, "too few string cases: {strs}");
    assert!(seqs >= 200, "too few sequence cases: {seqs}");
    assert!(dicts >= 100, "too few dict_diff cases: {dicts}");
    assert!(scores >= 100, "too few similarity_score cases: {scores}");
    assert!(
        autojunk_cases >= 200,
        "too few cases with len(b) >= 200 to exercise autojunk: {autojunk_cases}"
    );
}

#[test]
fn corpus_contains_the_named_edge_cases() {
    let records = load_corpus();

    let mut saw_empty_pair = false;
    let mut saw_identical = false;
    let mut saw_non_ascii = false;
    let mut saw_very_long = false;

    for record in &records {
        if record.field("kind").as_str() != "str" {
            continue;
        }
        let a = record.field("a").as_str();
        let b = record.field("b").as_str();
        if a.is_empty() && b.is_empty() {
            saw_empty_pair = true;
            assert_eq!(record.field("bits").as_u64(), 1.0f64.to_bits());
        }
        if !a.is_empty() && a == b {
            saw_identical = true;
        }
        if !a.is_ascii() || !b.is_ascii() {
            saw_non_ascii = true;
        }
        if b.chars().count() > 1000 {
            saw_very_long = true;
        }
    }

    assert!(saw_empty_pair, "corpus lacks the ratio(\"\", \"\") case");
    assert!(saw_identical, "corpus lacks identical-string cases");
    assert!(saw_non_ascii, "corpus lacks unicode cases");
    assert!(saw_very_long, "corpus lacks strings longer than 1000 chars");
}

#[test]
fn json_reader_handles_the_escape_forms_it_needs() {
    let mut parser = Parser::new(r#"{"a":"q\"\\\/\b\f\n\r\té🚀","n":-1.5e3}"#);
    let value = parser.parse();
    assert_eq!(
        value.field("a").as_str(),
        "q\"\\/\u{8}\u{c}\n\r\t\u{e9}\u{1f680}"
    );
    assert_eq!(value.field("n"), &Json::Num("-1.5e3".to_owned()));
}
